class TimeEncoderMixIn(object):
    Z_CHAR = ord('Z')
    PLUS_CHAR = ord('+')
    MINUS_CHAR = ord('-')
    COMMA_CHAR = ord(',')
    DOT_CHAR = ord('.')
    ZERO_CHAR = ord('0')

    MIN_LENGTH = 12
    MAX_LENGTH = 19

    def encodeValue(self, value, asn1Spec, encodeFun, **options):
        """Encode ASN.1 time value into CER."""
        if asn1Spec is None:
            substrate = value.asOctets()
        else:
            substrate = asn1Spec.clone(value).asOctets()

        # Check if the time string length is within allowed range
        if not (self.MIN_LENGTH <= len(substrate) <= self.MAX_LENGTH):
            raise error.PyAsn1Error(
                'Length constraint violated: %s not in %d..%d range' % 
                (len(substrate), self.MIN_LENGTH, self.MAX_LENGTH)
            )

        return encoder.OctetStringEncoder.encodeValue(
            self, value, asn1Spec, encodeFun, **options
        )

