        if self.PLUS_CHAR in substrate or self.MINUS_CHAR in substrate:
            raise error.PyAsn1Error('Local time zone is not allowed: %s' % (value,))

        if not substrate.endswith(bytes((self.Z_CHAR,))):
            raise error.PyAsn1Error('Missing time zone: %s' % (value,))

